<?php if($m=session()->getFlashdata('success')): ?><div class="alert success" role="status"><?= esc($m) ?></div><?php endif; ?><?php if($m=session()->getFlashdata('error')): ?><div class="alert danger" role="alert"><?= esc($m) ?></div><?php endif; ?><?php if($errors=session()->getFlashdata('errors')): ?><div class="alert danger" role="alert"><strong>Please correct the following:</strong><ul><?php foreach((array)$errors as $e): ?><li><?= esc($e) ?></li><?php endforeach; ?></ul></div><?php endif; ?>
